<?php
declare(strict_types=1);require_once __DIR__.'/includes/ui.php';pv_require_login();$db=pv_db();$uid=(int)$_SESSION['myid'];$notice='';$error='';
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){try{pv_require_csrf();$action=(string)($_POST['action']??'');$target=(int)($_POST['target']??0);if($action==='friend'&&$target>0){dn_friend_request($db,$uid,$target);$notice='Connection request synchronized.';}elseif($action==='remove'&&$target>0){dn_friend_remove($db,$uid,$target);$notice='Connection removed.';}}catch(Throwable $e){$error=$e->getMessage();}}
$q=trim((string)($_GET['q']??''));$rows=[];$sql='SELECT m.id,m.username,m.registered,m.wins,m.losses,m.totalexp,IF(bot.owner_id IS NULL,0,1) is_bot,COALESCE(o.tamer,m.created_avatar,1) tamer,CASE WHEN onl.time>='.(time()-900).' THEN 1 ELSE 0 END is_online FROM members m LEFT JOIN members_options o ON o.id=m.id LEFT JOIN online onl ON onl.id=m.id LEFT JOIN nxt_bots bot ON bot.owner_id=m.id WHERE m.banned=0 AND m.id<>?';if($q!=='')$sql.=' AND m.username LIKE ?';$sql.=' ORDER BY is_online DESC,m.totalexp DESC,m.username LIMIT 80';$stmt=$db->prepare($sql);if($stmt){if($q!==''){$like='%'.$q.'%';$stmt->bind_param('is',$uid,$like);}else $stmt->bind_param('i',$uid);$stmt->execute();$r=$stmt->get_result();while($x=$r->fetch_assoc())$rows[]=$x;$stmt->close();}
pv_page_start('Community','community.php',true);?>
<div class="pv-game-layout"><?php pv_game_side_menu('community.php');?><main class="pv-main-column"><section class="pv-page"><div class="pv-page-head"><?php nxt_page_sprites();?><div><span class="pv-eyebrow">NXT TAMER NETWORK</span><h1>Community</h1><p class="pv-subtle">Meet other players and the 1,000 AI rivals. Explore their teams and follow their progress.</p></div><form method="get" class="pv-actions"><input name="q" maxlength="45" placeholder="Search tamer" value="<?=pv_h($q)?>"><button class="pv-button pv-button-secondary">Search</button></form></div><?php if($notice):?><div class="pv-flash success"><?=pv_h($notice)?></div><?php endif;?><?php if($error):?><div class="pv-flash error"><?=pv_h($error)?></div><?php endif;?><div class="pv-trainer-grid"><?php foreach($rows as $m):$fs=dn_friend_status($db,$uid,(int)$m['id']);?><article class="pv-trainer-card"><div class="pv-trainer-avatar"><img src="<?=pv_h(nxt_skin_url((int)$m['tamer']))?>" alt=""></div><div class="pv-trainer-identity"><small class="<?=((int)$m['is_online']===1)?'pv-status-online':''?>"><?=!empty($m['is_bot'])?'AI RIVAL':(((int)$m['is_online']===1)?'PLAYER · ONLINE':'PLAYER · OFFLINE')?></small><h3><?=pv_h((string)$m['username'])?></h3><p><?=number_format((int)$m['totalexp'])?> EXP · <?=number_format((int)$m['wins'])?> wins</p><div class="pv-actions"><a class="pv-button pv-button-secondary" href="<?=pv_h(pv_url('profile.php?id='.(int)$m['id']))?>">Profile</a><?php if(empty($m['is_bot'])):?><form method="post"><?=pv_csrf_field()?><input type="hidden" name="target" value="<?=(int)$m['id']?>"><?php if(!$fs):?><button class="pv-button pv-button-secondary" name="action" value="friend">Connect</button><?php elseif($fs['status']==='accepted'):?><button class="pv-button pv-button-secondary" name="action" value="remove">Connected</button><?php elseif((int)$fs['requested_by']===$uid):?><button class="pv-button pv-button-secondary" disabled>Pending</button><?php else:?><button class="pv-button" name="action" value="friend">Accept</button><?php endif;?></form><?php else:?><a class="pv-button pv-button-secondary" href="<?=pv_h(pv_url('tamer_rivals.php'))?>">Rival records</a><?php endif;?></div></div></article><?php endforeach;?></div><?php if(!$rows):?><div class="pv-empty">No tamers match that search.</div><?php endif;?></section></main></div><?php pv_page_end(); ?>
